const input = $('Workflow Input').item.json;
const niche = input.NICHE || 'general';
let cfg = $input.all().find(n => n.json.NICHE_ID === niche)?.json || {
  NICHE_ID: niche, DISPLAY_NAME: niche, LANGUAGE: input.LANGUAGE || 'es',
  TONE: 'informativo, experto', AUDIENCE: 'lectores interesados en ' + niche,
  MIN_WORDS: 1200, MAX_WORDS: 1600, PROMPT_EXTRA: '', AFFILIATE_CATEGORY: 'general'
};
const lang = cfg.LANGUAGE || input.LANGUAGE || 'es';
const es = lang === 'es';
const monetBlock = es
? `BLOQUES OBLIGATORIOS en estas posiciones exactas:
1) Despues del 2do parrafo:
<div class="rec-productos"><h3>Productos recomendados</h3><ul>
<li><!-- PROD1_NAME --> - <a href="<!-- PROD1_URL -->" rel="nofollow sponsored" target="_blank">Ver en Amazon</a></li>
<li><!-- PROD2_NAME --> - <a href="<!-- PROD2_URL -->" rel="nofollow sponsored" target="_blank">Ver en Amazon</a></li>
<li><!-- PROD3_NAME --> - <a href="<!-- PROD3_URL -->" rel="nofollow sponsored" target="_blank">Ver en Amazon</a></li>
</ul></div>
2) Mitad del articulo despues de un H2:
<div class="cta-telegram"><p>💬 Dudas sobre ${cfg.DISPLAY_NAME}? Unete gratis: <a href="<!-- TELEGRAM_URL -->" target="_blank"><!-- TELEGRAM_NAME --></a></p></div>
3) Final del articulo:
<div class="cta-final"><p>📥 Descarga gratis: <a href="<!-- LEAD_MAGNET_URL -->" target="_blank"><!-- LEAD_MAGNET_NAME --></a></p></div>
En <!-- PRODX_NAME --> pon nombres de productos REALES del nicho. Deja URLs como placeholders exactos.`
: `MANDATORY BLOCKS at exact positions:
1) After 2nd paragraph:
<div class="rec-products"><h3>Recommended products</h3><ul>
<li><!-- PROD1_NAME --> - <a href="<!-- PROD1_URL -->" rel="nofollow sponsored" target="_blank">Check on Amazon</a></li>
<li><!-- PROD2_NAME --> - <a href="<!-- PROD2_URL -->" rel="nofollow sponsored" target="_blank">Check on Amazon</a></li>
<li><!-- PROD3_NAME --> - <a href="<!-- PROD3_URL -->" rel="nofollow sponsored" target="_blank">Check on Amazon</a></li>
</ul></div>
2) Mid-article after H2:
<div class="cta-telegram"><p>💬 Questions? Join free: <a href="<!-- TELEGRAM_URL -->" target="_blank"><!-- TELEGRAM_NAME --></a></p></div>
3) End of article:
<div class="cta-final"><p>📥 Free guide: <a href="<!-- LEAD_MAGNET_URL -->" target="_blank"><!-- LEAD_MAGNET_NAME --></a></p></div>
Fill PRODX_NAME with REAL product names. Keep URL placeholders exactly as shown.`;
const sys = es
  ? `Eres experto SEO y copywriter para ${cfg.DISPLAY_NAME}. Tono: ${cfg.TONE}. Escribe SOLO HTML puro, sin markdown.`
  : `Expert SEO writer for ${cfg.DISPLAY_NAME}. Tone: ${cfg.TONE}. Output ONLY pure HTML, no markdown.`;
const usr = es
? `Escribe en español.
Articulo: "${input.TITLE}"
Keywords: ${input.KEYWORDS||''}
Extension: ${cfg.MIN_WORDS}-${cfg.MAX_WORDS} palabras
Estructura: <h1> titulo, introduccion 2 parrafos, 4-5 <h2> con 2-3 parrafos, <strong> en terminos clave, conclusion CTA.
${cfg.PROMPT_EXTRA||''}
${monetBlock}
Empieza directamente con el HTML.`
: `Write in English.
Article: "${input.TITLE}"
Keywords: ${input.KEYWORDS||''}
Length: ${cfg.MIN_WORDS}-${cfg.MAX_WORDS} words
Structure: <h1> title, intro 2 paragraphs, 4-5 <h2> with 2-3 paragraphs, <strong> key terms, conclusion CTA.
${cfg.PROMPT_EXTRA||''}
${monetBlock}
Start directly with HTML.`;
return { json: { ...input, nicheConfig: cfg, systemPrompt: sys, userPrompt: usr, language: lang } };

const res = $('DeepSeek API').item.json;
const prev = $('Build Prompt + Monetizacion').item.json;
if (!res.choices) throw new Error('DeepSeek sin choices: ' + JSON.stringify(res).substring(0,300));
let html = (res.choices[0].message.content || '').trim();
if (!html || html.length < 200) throw new Error('HTML vacio o muy corto');
html = html.replace(/^```html\s*/i,'').replace(/^```\s*/i,'').replace(/\s*```\s*$/i,'').trim();
if (!html.includes('<h') || !html.includes('<p>')) throw new Error('HTML sin estructura valida');
const words = html.replace(/<[^>]+>/g,' ').split(/\s+/).filter(w=>w.length>2).length;
const tok = res.usage || {};
return { json: { ROW_NUMBER: prev.ROW_NUMBER, TITLE: prev.TITLE, BLOG_ID: prev.BLOG_ID, NICHE: prev.NICHE, LANGUAGE: prev.language, HTML_CONTENT: html, WORD_COUNT: words, TOKENS_USED: tok.total_tokens||0, TOKENS_INPUT: tok.prompt_tokens||0, TOKENS_OUTPUT: tok.completion_tokens||0, GENERATED_AT: new Date().toISOString(), HAS_MONETIZATION: html.includes('PROD1_NAME')||html.includes('cta-telegram') } };

const prev = $('Build Prompt + Monetizacion').item.json;
const retries = parseInt(prev.RETRY_COUNT||'0');
if (retries >= 2) throw new Error('DeepSeek fallo 3 veces consecutivas');
return { json: { ...prev, RETRY_COUNT: retries + 1 } };
